package com.franco.desco.adapter.in.web.crates;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.crates.*;import com.franco.desco.application.crates.port.in.CrateUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController@RequestMapping("/api/v1/jabas")@Tag(name="Control de jabas",description="Recepción, asignación, devolución, saldo e historial de jabas.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class CrateController{private final CrateUseCase u;private final CrateWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CrateController(CrateUseCase u,CrateWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'JABAS_LISTAR')")@Operation(operationId="jabasListar",summary="Listar control de jabas")public ResponseEntity<ApiResponse<PageResponse<CrateResponses.Summary>>>list(@RequestParam(required=false)Long operativoVentaId,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,operativoVentaId),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/saldo")@PreAuthorize("@permissionGuard.has(authentication,'JABAS_VER')")@Operation(operationId="jabasSaldo",summary="Consultar saldo de jabas")public ResponseEntity<ApiResponse<CrateResponses.Balance>>balance(@RequestParam Long operativoVentaId,@RequestParam(required=false)Long operativoSocioId,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.balance(new CrateCommands.Balance(operativoVentaId,operativoSocioId),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @GetMapping("/historial")@PreAuthorize("@permissionGuard.has(authentication,'JABAS_VER')")@Operation(operationId="jabasHistorial",summary="Consultar historial de movimientos")public ResponseEntity<ApiResponse<List<CrateResponses.History>>>history(@RequestParam(required=false)Long operativoVentaId,@RequestParam(required=false)Long operativoSocioId,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.history(new CrateCommands.History(operativoVentaId,operativoSocioId),ids.resolve(a),meta.resolve(r)),r,l->l.stream().map(map::response).toList());}
 @PostMapping("/recepciones")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'JABAS_EDITAR')")@Operation(operationId="jabasRegistrarRecepcion",summary="Registrar recepción de jabas en operativo")public ResponseEntity<ApiResponse<CrateResponses.Created>>receive(@Valid@RequestBody CrateRequests.Receive q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.receive(new CrateCommands.Receive(q.operativoVentaId(),q.cantidad(),q.referencia(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,CrateResponses.Created::new);}
 @PostMapping("/asignaciones")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'JABAS_CREAR')")@Operation(operationId="jabasAsignar",summary="Asignar jabas a socio")public ResponseEntity<ApiResponse<CrateResponses.Created>>assign(@Valid@RequestBody CrateRequests.Assign q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.assign(new CrateCommands.Assign(q.operativoSocioId(),q.cantidad(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,CrateResponses.Created::new);}
 @PostMapping("/devoluciones")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'JABAS_CREAR')")@Operation(operationId="jabasRegistrarDevolucion",summary="Registrar devolución de jabas")public ResponseEntity<ApiResponse<CrateResponses.Created>>returnCrates(@Valid@RequestBody CrateRequests.ReturnCrates q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.returnCrates(new CrateCommands.ReturnCrates(q.jabaAsignacionId(),q.entregaSocioId(),q.cantidadLlenas(),q.cantidadVacias(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,CrateResponses.Created::new);}
 @PostMapping("/movimientos/anular")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'JABAS_RETIRAR')")@Operation(operationId="jabasAnularMovimiento",summary="Anular movimiento autorizado")public ResponseEntity<ApiResponse<Void>>annul(@Valid@RequestBody CrateRequests.Annul q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.annul(new CrateCommands.Annul(q.tipo(),q.movimientoId(),q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
